# Real token validation would look roughly like:
def require_auth(handler):
    @wraps(handler)
    def wrapped(request):
        header = request.headers.get("Authorization", "")
        if not header.startswith("Bearer "):
            return {"status": 401, "body": {"error": "unauthorized"}}
        token = header.removeprefix("Bearer ")
        claims = verify_jwt(token, key=PUBLIC_KEY, algorithms=["RS256"])
        if claims is None or claims["exp"] < time.time():
            return {"status": 401, "body": {"error": "token expired or invalid"}}
        request.user = claims["sub"]
        return handler(request)
    return wrapped
```

The key additions vs the current stub: extract the Bearer token, verify the JWT signature against a public key, check expiry, and attach the authenticated identity (`sub` claim) to the request for downstream use.
